<?php
/** TEMP PS S1614 run e1d — D: deploy darbalaukis v3.15 (4 b64 dalys, md5 + token, gyvo failo sargas v3.14.2); T (naujas procesas): mygtukas „Pranešti klientui apie vėlavimą“ — skydelis #35435/#35421 (velavimas u+d), veiksmas #35435 kaip testuotojas per admin-post (nonce iš skydelio), po: žymė/pastaba/įvykis/laiškas (dev-pastas žurnalas), skydelis be mygtuko; Playwright: Klausimai + skydelis #35435 (po) + #35421 (su mygtuku). */
add_action('init', function(){
  if (!isset($_GET['ps_e1d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e1d'])); $o=array('v'=>'S1614 e1d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c4='';
    $p1=@file_get_contents($bk.'/dl-v315.part1'); $p2=@file_get_contents($bk.'/dl-v315.part2'); $p3=@file_get_contents($bk.'/dl-v315.part3'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen((string)$p3),strlen($c4));
    $code=base64_decode($p1.$p2.$p3.$c4,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='488142d766f60c8e305b95b6028c046c') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t);
    if ($o['buvo']!=='165871eb0c83297ebdfd637416ed6d53') { $o['STOP']='gyvas ne v3.14.2 ('.$o['buvo'].')'; $J($o); }
    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v3142-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v315.part1'); @unlink($bk.'/dl-v315.part2'); @unlink($bk.'/dl-v315.part3');
  }
  if($f==='T'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['dev_zurnalas_pries']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    add_filter('pre_wp_mail',function($r,$a){ $m=get_option('ps_e1_mail',array()); $m[]=array('to'=>is_array($a['to'])?implode(',',$a['to']):$a['to'],'s'=>$a['subject']); update_option('ps_e1_mail',$m,false); return true; },4,2);
    $o['now']=current_time('mysql');
    $tu=get_user_by('login','testuotojas'); $uid=$tu->ID; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp);
    $li=wp_generate_auth_cookie($uid,$exp,'logged_in',$tok); $_COOKIE[LOGGED_IN_COOKIE]=$li; wp_set_current_user($uid);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>$li)));
    $n=wp_create_nonce('ps_dl_zurnalas');
    $sk=function($id) use ($cs,$n){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$id.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $b=is_wp_error($r)?'':wp_remote_retrieve_body($r); $j=json_decode($b,true); $d=$j['data']??array(); return array('code'=>wp_remote_retrieve_response_code($r),'kl'=>$d['klausimas']??null,'kur'=>$d['kur']??null,'btn'=>$d['btn']['t']??null,'pastaba'=>$d['pastaba']??null,'apmok'=>$d['apmok']??null,'st'=>$d['st']??null,'velavimas'=>$d['velavimas']??null); };
    $bk=function($id){ global $wpdb; $x=wc_get_order($id); $nt=wc_get_order_notes(array('order_id'=>$id,'limit'=>1)); $ev=$wpdb->get_row($wpdb->prepare('SELECT veiksmas,rezultatas,kanalas,kas_vardas,laikas,pastaba FROM '.Petshop_Uzsakymu_Ivykiai::t().' WHERE uzsakymas=%d ORDER BY id DESC LIMIT 1',$id),ARRAY_A); return array('st'=>$x->get_status(),'vel'=>(string)$x->get_meta('_ps_velavimo_laiskas'),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta'),'pastaba'=>$nt?mb_substr($nt[0]->content,0,220):null,'ivykis'=>$ev); };
    foreach(array(35435,35421) as $id){ $o['pries'][$id]=$bk($id); $o['sk_pries'][$id]=$sk($id); }
    // veiksmas #35435 kaip testuotojas — URL su nonce iš skydelio atsakymo
    $u=$o['sk_pries'][35435]['velavimas']['u']??''; $o['veiksmo_url']=$u?preg_replace('/_wpnonce=[a-f0-9]+/','_wpnonce=…',$u):'nėra';
    if($u){ $r=wp_remote_get(html_entity_decode($u),array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false,'redirection'=>0)); $o['veiksmas']=array('code'=>wp_remote_retrieve_response_code($r),'loc'=>urldecode((string)wp_remote_retrieve_header($r,'location')),'body'=>mb_substr(wp_strip_all_tags((string)wp_remote_retrieve_body($r)),0,200)); }
    $o['po'][35435]=$bk(35435); $o['sk_po'][35435]=$sk(35435);
    $o['laiskai_sis_procesas']=get_option('ps_e1_mail',array()); delete_option('ps_e1_mail');
    $z=(array)get_option('ps_dev_pastas_zurnalas',array()); $o['dev_zurnalas_po']=count($z); $last=end($z); $o['dev_zurnalas_paskutinis']=is_array($last)?array_map(function($v){ return is_string($v)?mb_substr(preg_replace('/\s+/',' ',wp_strip_all_tags($v)),0,400):$v; },$last):$last;
    wp_set_current_user(0);
    $o['cookies']=array(); foreach($cs as $c){ $o['cookies'][]=array('name'=>$c->name,'value'=>$c->value); }
    $evk="({korteles:[...document.querySelectorAll('.dl-kortele')].map(x=>x.innerText.replace(/\\s+/g,' ').slice(0,260)),mygtukai:[...document.querySelectorAll('.dl-kortele a,.dl-kortele button')].map(x=>x.innerText).filter(t=>/vėlavim/.test(t))})";
    $evs="({v:(document.getElementById('skV')||{innerText:''}).innerText.replace(/\\s+/g,' '),pastaba:(document.getElementById('skPastaba')||{innerText:''}).innerText.replace(/\\s+/g,' ').slice(0,300),pill:[...document.querySelectorAll('.dl-pill')].map(x=>x.innerText).filter(t=>/vėlavim/.test(t))})";
    $evd="({dlg:(document.getElementById('dlDlgT')||{textContent:''}).textContent.slice(0,400),ok:(document.getElementById('dlDlgOk')||{textContent:''}).textContent,on:!!(document.getElementById('dlDlg')||{}).classList&&document.getElementById('dlDlg').classList.contains('on')})";
    $o['shots']=array(
      array('n'=>'s1614_e1_klausimai','u'=>admin_url('admin.php?page=ps-desk&eile=klausimai'),'w'=>1400,'full'=>true,'eval'=>$evk),
      array('n'=>'s1614_e1_skydelis_35435_po','u'=>admin_url('admin.php?page=ps-desk&eile=visi&q=35435&atidaryti=35435'),'w'=>1400,'eval'=>$evs),
      array('n'=>'s1614_e1_skydelis_35421','u'=>admin_url('admin.php?page=ps-desk&eile=visi&q=35421&atidaryti=35421'),'w'=>1400,'eval'=>$evs),
      array('n'=>'s1614_e1_dialogas_35421','u'=>admin_url('admin.php?page=ps-desk&eile=visi&q=35421&atidaryti=35421'),'w'=>1400,'click'=>'#skV a:has-text("Pranešti klientui apie vėlavimą")','eval'=>$evd)
    );
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
},99);
